package com.jamshed.hrms.config;
import com.jamshed.hrms.entity.*;import com.jamshed.hrms.repository.*;import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.*;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import java.time.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.beans.factory.annotation.Value;import org.springframework.security.crypto.password.PasswordEncoder;
@Configuration @ConditionalOnProperty(name="app.demo.seed", havingValue="true") public class DataSeeder{@Bean CommandLineRunner seed(DepartmentRepository dr,EmployeeRepository er,AppUserRepository ur,LeaveRequestRepository lr,AttendanceRepository ar,TimesheetRepository tr,PayrollRepository pr,CandidateRepository cr, PasswordEncoder enc, @Value("${app.demo.admin-email}") String adminEmail, @Value("${app.demo.admin-password}") String adminPassword){return args->{if(er.count()>0)return;if(adminPassword == null || adminPassword.length()<12) throw new IllegalStateException("Set DEMO_ADMIN_PASSWORD (minimum 12 characters) for demo seeding");Department eng=dr.save(Department.builder().name("Engineering").code("ENG").description("Product engineering").active(true).build());Department hr=dr.save(Department.builder().name("Human Resources").code("HR").description("People operations").active(true).build());Department sales=dr.save(Department.builder().name("Sales").code("SAL").description("Enterprise sales").active(true).build());Employee admin=er.save(Employee.builder().employeeCode("EMP-1001").firstName("Alex").lastName("Morgan").email(adminEmail).phone("0000000000").jobTitle("HRMS Administrator").location("Lucknow").joinDate(LocalDate.of(2023,1,10)).department(eng).status("ACTIVE").managerName("Engineering Director").build());Employee maya=er.save(Employee.builder().employeeCode("EMP-1002").firstName("Maya").lastName("Sharma").email("maya@hrms.dev").phone("0000000002").jobTitle("HR Manager").location("Noida").joinDate(LocalDate.of(2024,3,4)).department(hr).status("ACTIVE").managerName("VP People").build());Employee arjun=er.save(Employee.builder().employeeCode("EMP-1003").firstName("Arjun").lastName("Verma").email("arjun@hrms.dev").phone("0000000003").jobTitle("Sales Lead").location("Delhi").joinDate(LocalDate.of(2022,7,12)).department(sales).status("ACTIVE").managerName("Sales Director").build());ur.save(AppUser.builder().email(adminEmail).passwordHash(enc.encode(adminPassword)).role("ADMIN").enabled(true).employee(admin).build());lr.save(LeaveRequest.builder().employee(maya).leaveType("ANNUAL").startDate(LocalDate.now().plusDays(5)).endDate(LocalDate.now().plusDays(7)).reason("Family trip").status("PENDING").createdAt(LocalDateTime.now()).build());ar.save(Attendance.builder().employee(admin).workDate(LocalDate.now()).checkIn(LocalDateTime.now().withHour(9).withMinute(15)).status("PRESENT").build());tr.save(Timesheet.builder().employee(admin).weekStart(LocalDate.now().minusDays(LocalDate.now().getDayOfWeek().getValue()-1)).hours(40.0).projectName("HRMS Modernization").status("SUBMITTED").notes("Frontend and API integration").build());pr.save(Payroll.builder().employee(admin).month("October 2026").basicSalary(90000.0).allowances(30000.0).deductions(5000.0).netSalary(115000.0).status("PAID").paidOn(LocalDate.now().minusDays(2)).build());cr.save(Candidate.builder().name("Aditi Singh").email("aditi@example.com").phone("0000000011").position("Angular Developer").stage("INTERVIEW").experienceYears(4).source("LinkedIn").build());cr.save(Candidate.builder().name("Rohit Kumar").email("rohit@example.com").phone("0000000012").position("Java Developer").stage("APPLIED").experienceYears(5).source("Referral").build());};}}
